152	  auto check_datatype = [&](const IndexMeta & /*target_meta*/,
153	                            const IndexMeta &source_meta) -> bool {
154	    if (target_builder_ && !is_sparse_) {
155	      // Builders consume decoded vectors. Legacy and Turbo postings can
156	      // describe different stored types for the same original input type.
157	      // Validate each decoded record against original_query_meta_ in read_vec.
158	      return true;
159	    }
160	    if (!streamers_.empty()) {
161	      auto &last_meta = streamers_.back()->meta();
162	      // Quantizer-encoded sources are dequantized to the original format
163	      // before the target re-encodes them, so their stored layout may
164	      // legitimately differ from another source's.
165	      if (!last_meta.quantizer_name().empty() ||
166	          !source_meta.quantizer_name().empty()) {
167	        return true;
168	      }
169	      return last_meta.data_type() == source_meta.data_type() &&
170	             last_meta.dimension() == source_meta.dimension() &&
171	             last_meta.unit_size() == source_meta.unit_size();
172	    }
173	    // TODO: check target meta
174	    return true;
175	  };
