206	int MixedStreamerReducer::reduce(const IndexFilter &filter) {
207	  if (state_ != STATE_FEED) {
208	    LOG_ERROR("Feed streamers first");
209	    return IndexError_Uninitialized;
210	  }
211	  if (thread_pool_ == nullptr) {
212	    LOG_ERROR("Thread pool is not set");
213	    return IndexError_Uninitialized;
214	  }
215	
216	  ailego::ElapsedTime timer;
217	
218	  if (target_builder_ != nullptr) {
219	    if (is_sparse_) {
220	      LOG_ERROR("Builder-backed sparse merge is not supported");
221	      return IndexError_Unsupported;
222	    }
223	    int ret = this->reduce_with_builder(filter);
224	    if (ret != 0) {
225	      LOG_ERROR("Failed to build target index, ret=%d", ret);
226	      return ret;
227	    }
228	    stats_.set_reduced_costtime(timer.seconds());
229	    state_ = STATE_REDUCE;
230	    LOG_INFO("End provider-backed reduce. cost time: [%zu]s",
231	             (size_t)timer.seconds());
232	    return 0;
233	  }
234	
235	  std::vector<int> add_results(num_of_add_threads_, -1);
