232	int PqInt8Quantizer::train(IndexHolder::Pointer holder) {
233	  if (!holder) {
234	    return kErrUnsupported;
235	  }
236	
237	  const size_t input_count = holder->count();
238	  const uint32_t elem_size = element_size();
239	  const size_t vec_bytes = static_cast<size_t>(original_dim_) * elem_size;
240	  if (!input_count || holder->dimension() != original_dim_ ||
241	      holder->element_size() != vec_bytes ||
242	      holder->data_type() != (input_data_type_ == DataType::kFp16
243	                                  ? IndexMeta::DataType::DT_FP16
244	                                  : IndexMeta::DataType::DT_FP32)) {
245	    return kErrUnsupported;
246	  }
247	  size_t num = std::min(input_count, static_cast<size_t>(kMaxTrainVectors));
248	  if (num > std::numeric_limits<size_t>::max() / vec_bytes) {
249	    return kErrUnsupported;
250	  }
251	
252	  std::vector<uint8_t> all_data;
253	  if (!CollectPqTrainingSamples(holder, kMaxTrainVectors, vec_bytes,
254	                                &all_data)) {
255	    return kErrUnsupported;
256	  }
257	  holder.reset();
258	
259	  size_t data_stride = original_dim_ * elem_size;
260	
261	  // For Cosine: normalize training data so centroids are learned in
262	  // normalized space (L2 minimization == maximizing cosine similarity).
263	  if (meta_.metric_name() == "Cosine") {
264	    switch (input_data_type_) {
265	      case DataType::kFp16:
266	        normalize(reinterpret_cast<ailego::Float16 *>(all_data.data()), num);
267	        break;
268	      case DataType::kFp32:
269	        normalize(reinterpret_cast<float *>(all_data.data()), num);
270	        break;
271	      default:
272	        break;
273	    }
274	  }
275	
276	  // Zero-mean centering: subtract the per-dimension mean; the centroid is
277	  // saved for quantize_data / quantize_query / dequantize.  For Cosine this
278	  // runs AFTER normalization, so all paths keep the same order
279	  // (normalize -> center; dequantize: un-center -> rescale).
280	  if (use_zero_mean_) {
281	    switch (input_data_type_) {
282	      case DataType::kFp16:
283	        compute_and_subtract_center(
284	            reinterpret_cast<ailego::Float16 *>(all_data.data()), num);
285	        break;
286	      case DataType::kFp32:
287	        compute_and_subtract_center(reinterpret_cast<float *>(all_data.data()),
288	                                    num);
289	        break;
290	      default:
291	        break;
292	    }
293	  }
294	
295	  opq_.train(
296	      all_data.data(), num, "PqInt8Quantizer",
297	      [&](uint32_t max_iters) {
298	        train_all_chunks(all_data.data(), num, data_stride, max_iters);
299	        build_centroid_ptrs_cache();
300	      },
301	      [this](const float *rotated, size_t count, float *x_hat) {
302	        return encode_reconstruct_batch(rotated, count, x_hat);
303	      });
304	
305	  train_all_chunks(all_data.data(), num, data_stride, kMaxKmeansIters);
306	
307	  // Pre-build centroid pointer cache (needed by compute_dist_table).
308	  build_centroid_ptrs_cache();
309	
310	  // Pre-compute SDC dist_table.
311	  compute_dist_table();
312	
313	  // Pre-compute sub-centroid norms for the precomputed residual table.
314	  compute_sub_centroid_norms();
315	
316	  return 0;
